// Subsets: O(n * 2^n)
function subsets(nums) {
  const res = [], path = [];
  (function dfs(start) {
    res.push([...path]);                 // record a COPY at every node
    for (let i = start; i < nums.length; i++) {
      path.push(nums[i]);                // choose
      dfs(i + 1);                        // explore
      path.pop();                        // un-choose
    }
  })(0);
  return res;
}

// Permutations: O(n * n!)
function permutations(nums) {
  const res = [], path = [], used = new Array(nums.length).fill(false);
  (function dfs() {
    if (path.length === nums.length) { res.push([...path]); return; }
    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue;
      used[i] = true; path.push(nums[i]);
      dfs();
      path.pop(); used[i] = false;
    }
  })();
  return res;
}

// Combination sum (reuse allowed), pruned. Sort first.
function combinationSum(candidates, target) {
  candidates.sort((a, b) => a - b);
  const res = [], path = [];
  (function dfs(start, remaining) {
    if (remaining === 0) { res.push([...path]); return; }
    for (let i = start; i < candidates.length; i++) {
      if (candidates[i] > remaining) break;      // prune
      path.push(candidates[i]);
      dfs(i, remaining - candidates[i]);         // i, not i+1: reuse allowed
      path.pop();
    }
  })(0, target);
  return res;
}

// Subsets: O(n * 2^n)
static List<List<Integer>> subsets(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    dfs(nums, 0, new ArrayList<>(), res);
    return res;
}
static void dfs(int[] nums, int start, List<Integer> path, List<List<Integer>> res) {
    res.add(new ArrayList<>(path));              // copy
    for (int i = start; i < nums.length; i++) {
        path.add(nums[i]);                       // choose
        dfs(nums, i + 1, path, res);             // explore
        path.remove(path.size() - 1);            // un-choose
    }
}

// Subsets: O(n * 2^n)
void dfs(const vector<int>& nums, int start, vector<int>& path, vector<vector<int>>& res) {
    res.push_back(path);                         // copy
    for (int i = start; i < (int)nums.size(); i++) {
        path.push_back(nums[i]);                 // choose
        dfs(nums, i + 1, path, res);             // explore
        path.pop_back();                         // un-choose
    }
}
vector<vector<int>> subsets(const vector<int>& nums) {
    vector<vector<int>> res; vector<int> path;
    dfs(nums, 0, path, res);
    return res;
}

// Climbing stairs: O(n) time, O(1) space
function climbStairs(n) {
  let prev = 1, curr = 1;
  for (let i = 2; i <= n; i++) [prev, curr] = [curr, prev + curr];
  return curr;
}

// House robber: O(n) time, O(1) space
function rob(money) {
  let skip = 0, take = 0; // best up to previous house / up to the one before
  for (const m of money) [skip, take] = [Math.max(skip, take + m), skip];
  return skip;
}

// Coin change (fewest coins), bottom-up: O(amount * coins)
function coinChange(coins, amount) {
  const dp = new Array(amount + 1).fill(Infinity);
  dp[0] = 0;
  for (let a = 1; a <= amount; a++)
    for (const c of coins)
      if (c <= a) dp[a] = Math.min(dp[a], dp[a - c] + 1);
  return dp[amount] === Infinity ? -1 : dp[amount];
}

